import { test, expect } from '@playwright/test';

test.describe('Recorded Test', () => {
  test('should complete recorded Test successfully', async ({ page }) => {
    // Fill "mum" in the From
    await page.locator('#origin').fill('mum')

    // Click the BOM — Mumbai
    await page.getByLabel('BOM — Mumbai').click()
    await expect.soft(page.locator('[data-auto-id="cart-count"]')).toContainText('0')

    // Click the Search flights
    await page.locator('#go').click()
    await expect.soft(page.locator('[data-auto-id="cart-count"]')).toContainText('0')

    // Click the Add extras for flight AI-887
    await page.getByLabel('Add extras for flight AI-887').click()
    await expect.soft(page.locator('[data-auto-id="cart-count"]')).toContainText('0')

    // Click the Add meal to flight AI-887
    await page.getByLabel('Add meal to flight AI-887').click()
    await expect.soft(page.locator('[data-auto-id="cart-count"]')).toContainText('1')

    // Click the "Cart" link
    await page.getByLabel('Cart').click()
    await expect.soft(page.locator('[data-auto-id="cart-count"]')).toContainText('1')
    await expect.soft(page.locator('[data-auto-id="cart-total"]')).toContainText('1')
    await expect.soft(page.locator('[data-sku="MEAL"]')).toBeAttached()

    // Click the Increase quantity of MEAL
    await page.getByLabel('Increase quantity of MEAL').click()
    await expect.soft(page.locator('[data-auto-id="cart-count"]')).toContainText('2')
    await expect.soft(page.locator('[data-auto-id="cart-total"]')).toContainText('2')
    await expect.soft(page.locator('[data-sku="MEAL"]')).toBeAttached()

    // Click the Increase quantity of MEAL
    await page.getByLabel('Increase quantity of MEAL').click()
    await expect.soft(page.locator('[data-auto-id="cart-count"]')).toContainText('3')
    await expect.soft(page.locator('[data-auto-id="cart-total"]')).toContainText('3')
    await expect.soft(page.locator('[data-sku="MEAL"]')).toBeAttached()
  });
});
